definition.frag:
vec2 st = v_st;
float aspect = u_res.x / max(u_res.y, 1.0);
vec2 p = (st - 0.5) * vec2(aspect, 1.0);
float d = length(p);
float soft = max(u_softness, 1e-4);
float maxR = 0.5 * sqrt(aspect * aspect + 1.0);
float prog = clamp(u_prog, 0.0, 1.0);
float r = prog * (maxR + soft);
float m = 1.0 - smoothstep(r - soft, r, d);
m = prog <= 0.0 ? 0.0 : (prog >= 1.0 ? 1.0 : m);
vec4 a = texture(u_from, st);
vec4 b = texture(u_to, st);
o = mix(a, b, m);
